from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import refund_shipping
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(): return Payment("p","i",Decimal("100.00"),status="captured",created_at=T0,captured_at=T0)

p=mk(); refund_shipping(p,Decimal("100.00"),T0); print("full:",p.refunded_amount,p.status)
p=mk()
for a in ["10.00","20.00"]:
    refund_shipping(p,Decimal(a),T0)
print("partial:",p.refunded_amount,p.status)
for bad in [Decimal("0"),Decimal("-1")]:
    try: refund_shipping(mk(),bad,T0)
    except BillingError as e: print("bad amount:",e.code)
try: refund_shipping(mk(),Decimal("101.00"),T0)
except BillingError as e: print("over:",e.code)
try: refund_shipping(mk(),Decimal("600.00"),T0)
except BillingError as e: print("approval:",e.code)
p=mk(); refund_shipping(p,Decimal("600.00"),T0,approved_by="mgr"); print("approved:",p.refunded_amount)
p=mk(); refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k"); refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k"); print("idem:",p.refunded_amount)
try: refund_shipping(Payment("p","i",Decimal("10"),status="authorized"),Decimal("1"),T0)
except BillingError as e: print("state:",e.code)
try: refund_shipping(mk(),Decimal("1"),datetime(2026,1,1))
except BillingError as e: print("naive:",e.code)
EOF"}

